(function() {
    'use strict';

    class BancaVerdeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Disrupción Fintech: BancaVerde';
            this.version = '1.2.0';

            this.ROUNDS = [
                {
                    titleKey: 'r1_title',
                    descKey: 'r1_desc',
                    partnerOptions: [
                        { id: 'finpago', labelKey: 'partner_r1_finpago' },
                        { id: 'agricredit', labelKey: 'partner_r1_agricredit' },
                        { id: 'techbank', labelKey: 'partner_r1_techbank' },
                        { id: 'none', labelKey: 'partner_r1_none' }
                    ],
                    productOptions: [
                        { id: 'none', labelKey: 'product_none', cost: 0 },
                        { id: 'digital_account', labelKey: 'product_r1_digital_account', cost: 12, dpBonus: 5, msBonus: 0.8 },
                        { id: 'bnpl', labelKey: 'product_r1_bnpl', cost: 25, dpBonus: 2, msBonus: 0.5, ecoBonus: 15 },
                        { id: 'sme_suite', labelKey: 'product_r1_sme_suite', cost: 45, dpBonus: 1, msBonus: 0.5, roeBonus: 0.3 },
                        { id: 'remittances', labelKey: 'product_r1_remittances', cost: 8, dpBonus: 3, ecoBonus: 10 }
                    ]
                },
                {
                    titleKey: 'r2_title',
                    descKey: 'r2_desc',
                    partnerOptions: [
                        { id: 'acquire', labelKey: 'partner_r2_acquire' },
                        { id: 'partner', labelKey: 'partner_r2_partner' },
                        { id: 'reject', labelKey: 'partner_r2_reject' }
                    ],
                    productOptions: [
                        { id: 'none', labelKey: 'product_none', cost: 0 },
                        { id: 'investment_app', labelKey: 'product_r2_investment_app', cost: 80, dpBonus: 4, roeBonus: 0.5, msBonus: 0.3 },
                        { id: 'baas_platform', labelKey: 'product_r2_baas_platform', cost: 120, ecoBonus: 40, roeBonus: 0.2 },
                        { id: 'ai_credit', labelKey: 'product_r2_ai_credit', cost: 35, costIncomeBonus: -3, roeBonus: 0.4 }
                    ]
                },
                {
                    titleKey: 'r3_title',
                    descKey: 'r3_desc',
                    partnerOptions: [
                        { id: 'ecosystem_leader', labelKey: 'partner_r3_ecosystem_leader' },
                        { id: 'niche_sme', labelKey: 'partner_r3_niche_sme' },
                        { id: 'acquisition_ready', labelKey: 'partner_r3_acquisition_ready' }
                    ],
                    productOptions: [
                        { id: 'none', labelKey: 'product_none', cost: 0 },
                        { id: 'data_monetization', labelKey: 'product_r3_data_monetization', cost: 30, ecoBonus: 25, roeBonus: 0.3 },
                        { id: 'ai_advisor', labelKey: 'product_r3_ai_advisor', cost: 50, dpBonus: 5, npsBonus: 8, roeBonus: 0.2 },
                        { id: 'open_finance_market', labelKey: 'product_r3_open_finance_market', cost: 60, ecoBonus: 35, msBonus: 0.8, dpBonus: 3 }
                    ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    marketShare: 17.0,
                    digitalPenetration: 34.0,
                    digitalNPS: 28,
                    costToIncome: 68.0,
                    nim: 4.2,
                    roe: 11.0,
                    techDebt: 800,
                    brandTrust: 50,
                    apiReady: 0,
                    ecosystemRevenue: 0,
                    engineerTeams: 0,
                    branchesClosed: 0,
                    regulatoryFined: false,
                    acquisitionChoice: 'none',
                    finalPositioning: 'none',
                    periodScore: 0,
                    totalScore: 0,
                    scoreFinancial: 0,
                    scoreDigital: 0,
                    scoreMarket: 0,
                    scoreOrg: 0,
                    scoreHistory: [],
                    marketShareHistory: [],
                    digitalPenHistory: [],
                    roeHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    coreBanking: 15,
                    mobileUX: 15,
                    dataAI: 10,
                    cybersecurity: 10,
                    openBankingAPI: 25,
                    branchTech: 25,
                    partnership: 'none',
                    product: 'none',
                    branchClosures: 0,
                    engineerHires: 0
                };
            }
            // Safety: ensure arrays always exist even after partial DB restore
            if (!Array.isArray(state.domainState.scoreHistory))       state.domainState.scoreHistory       = [];
            if (!Array.isArray(state.domainState.marketShareHistory)) state.domainState.marketShareHistory = [];
            if (!Array.isArray(state.domainState.digitalPenHistory))  state.domainState.digitalPenHistory  = [];
            if (!Array.isArray(state.domainState.roeHistory))         state.domainState.roeHistory         = [];

            // Undo rollback: the USF framework rewinds currentPeriod and re-calls initialize
            // but does NOT restore domainState. If domainState is ahead of the current period
            // (multi-level undo), restore the entry snapshot for this period so KPIs and the
            // score history roll back correctly instead of compounding (fix v1.2.0).
            var __cp = state.currentPeriod || 1;
            var __dsi = state.domainState;
            if (__dsi._periodSnapshots && __dsi._periodSnapshots[__cp] &&
                typeof __dsi._snapshotPeriod === 'number' && __dsi._snapshotPeriod > __cp) {
                var __restore = __dsi._periodSnapshots[__cp];
                Object.keys(__restore).forEach(function(k) { __dsi[k] = JSON.parse(JSON.stringify(__restore[k])); });
                __dsi._snapshotPeriod = __cp;
                __dsi._periodStartSnapshot = JSON.parse(JSON.stringify(__restore));
                Object.keys(__dsi._periodSnapshots).forEach(function(k) { if (+k > __cp) delete __dsi._periodSnapshots[k]; });
            }

            this._setupSliderListeners();
            this._updateBriefing(state);
            this._updatePartnershipOptions(state);
            this._updateProductOptions(state);
        }

        _setupSliderListeners() {
            var sliderIds = ['coreBanking', 'mobileUX', 'dataAI', 'cybersecurity', 'api', 'branchTech'];
            var valIds    = ['coreBankingVal', 'mobileUXVal', 'dataAIVal', 'cyberVal', 'apiVal', 'branchTechVal'];
            var inputIds  = ['coreBankingSlider', 'mobileUXSlider', 'dataAISlider', 'cyberSlider', 'apiSlider', 'branchTechSlider'];

            function updateBudgetTotal() {
                var total = 0;
                inputIds.forEach(function(id) {
                    var el = document.getElementById(id);
                    if (el) total += parseInt(el.value) || 0;
                });
                var totalEl = document.getElementById('budgetTotal');
                if (totalEl) totalEl.textContent = total;
                var warnEl = document.getElementById('budgetWarning');
                var okEl   = document.getElementById('budgetOk');
                if (warnEl && okEl) {
                    if (total !== 100) {
                        warnEl.style.display = 'inline';
                        okEl.style.display = 'none';
                        var totalValEl = document.getElementById('budgetTotal');
                        if (totalValEl) totalValEl.style.color = '#dc3545';
                    } else {
                        warnEl.style.display = 'none';
                        okEl.style.display = 'inline';
                        var totalValEl2 = document.getElementById('budgetTotal');
                        if (totalValEl2) totalValEl2.style.color = '#28a745';
                    }
                }
            }

            inputIds.forEach(function(id, i) {
                var el = document.getElementById(id);
                var valEl = document.getElementById(valIds[i]);
                if (el && valEl) {
                    el.addEventListener('input', function() {
                        valEl.textContent = el.value + '%';
                        updateBudgetTotal();
                    });
                }
            });

            updateBudgetTotal();
        }

        validateDecisions(decisions) {
            decisions.coreBanking    = parseInt(document.getElementById('coreBankingSlider').value) || 0;
            decisions.mobileUX       = parseInt(document.getElementById('mobileUXSlider').value) || 0;
            decisions.dataAI         = parseInt(document.getElementById('dataAISlider').value) || 0;
            decisions.cybersecurity  = parseInt(document.getElementById('cyberSlider').value) || 0;
            decisions.openBankingAPI = parseInt(document.getElementById('apiSlider').value) || 0;
            decisions.branchTech     = parseInt(document.getElementById('branchTechSlider').value) || 0;

            var total = decisions.coreBanking + decisions.mobileUX + decisions.dataAI +
                        decisions.cybersecurity + decisions.openBankingAPI + decisions.branchTech;

            if (total !== 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_must_100_msg') + total + '%', 'warning'
                );
                return false;
            }

            var partnerRadios = document.querySelectorAll('.bv-partner-radio');
            decisions.partnership = 'none';
            partnerRadios.forEach(function(r) {
                if (r.checked) decisions.partnership = r.value;
            });

            var productSel = document.getElementById('productSelect');
            if (productSel) decisions.product = productSel.value;

            decisions.branchClosures = parseInt(document.getElementById('branchClosuresInput').value) || 0;
            decisions.engineerHires  = parseInt(document.getElementById('engineerHiresInput').value) || 0;

            if (decisions.branchClosures < 0 || decisions.branchClosures > 50) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('branch_closures_warning'), 'warning');
                return false;
            }
            if (decisions.engineerHires < 0 || decisions.engineerHires > 5) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('engineer_warning'), 'warning');
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d      = state.decisions;
            var ds     = state.domainState;
            var period = state.currentPeriod;
            var round  = this.ROUNDS[period - 1];

            // Safety: guarantee history arrays exist (defensive against partial restore)
            if (!Array.isArray(ds.scoreHistory))       ds.scoreHistory       = [];
            if (!Array.isArray(ds.marketShareHistory)) ds.marketShareHistory = [];
            if (!Array.isArray(ds.digitalPenHistory))  ds.digitalPenHistory  = [];
            if (!Array.isArray(ds.roeHistory))         ds.roeHistory         = [];

            // --- Idempotency guard (fix for B1, testing/review_002_standalone_replay.md) ---
            // This function mutates ds with relative (+=/-=) deltas. Resubmitting the SAME
            // period (a double-click on submit, or Undo followed by resubmitting the same
            // or changed decisions) would otherwise re-apply deltas on top of already-mutated
            // values and silently corrupt the score. Fix: snapshot domainState once per period
            // (before that period's deltas are applied); every call for the same period
            // restores that snapshot first, then recomputes fresh from current decisions.
            var __snapKeys = Object.keys(ds).filter(function(k) { return k.indexOf('_') !== 0; });
            if (ds._snapshotPeriod === period && ds._periodStartSnapshot) {
                var __restore = ds._periodStartSnapshot;
                __snapKeys.forEach(function(k) { ds[k] = JSON.parse(JSON.stringify(__restore[k])); });
            } else {
                var __snap = {};
                __snapKeys.forEach(function(k) { __snap[k] = ds[k]; });
                ds._periodStartSnapshot = JSON.parse(JSON.stringify(__snap));
                ds._snapshotPeriod = period;
                // Keep a per-period map of entry snapshots so multi-level Undo (jumping back
                // more than one period) can also roll domainState back correctly (fix v1.2.0).
                ds._periodSnapshots = ds._periodSnapshots || {};
                ds._periodSnapshots[period] = JSON.parse(JSON.stringify(__snap));
            }

            // Budget allocation effects
            ds.apiReady          += d.coreBanking * 0.4;
            ds.costToIncome      -= d.coreBanking * 0.08;
            ds.techDebt           = Math.max(0, ds.techDebt - 280 * d.coreBanking / 100 * 1.5);

            ds.digitalPenetration += d.mobileUX * 0.35;
            ds.digitalNPS         += Math.round(d.mobileUX * 0.25);
            ds.marketShare        += d.mobileUX * 0.02;

            ds.costToIncome -= d.dataAI * 0.12;
            ds.roe          += d.dataAI * 0.04;

            ds.brandTrust += d.cybersecurity * 0.15;

            ds.apiReady         += d.openBankingAPI * 1.0;
            ds.ecosystemRevenue += d.openBankingAPI * 0.8;
            ds.marketShare      += d.openBankingAPI * 0.01;

            ds.costToIncome       -= d.branchTech * 0.04;
            ds.digitalPenetration += d.branchTech * 0.1;

            ds.apiReady = Math.min(100, ds.apiReady);

            // Partnership and period-specific events
            var partnerNarrative = '';
            var regEvent = '';

            if (period === 1) {
                if (d.partnership === 'finpago') {
                    ds.marketShare      += 0.5;
                    ds.ecosystemRevenue += 20;
                    ds.brandTrust       -= 5;
                    partnerNarrative = 'Integración con FinPago completada: +0.5% participación de mercado, AV$20M en ingresos de ecosistema.';
                } else if (d.partnership === 'agricredit') {
                    ds.marketShare      += 1.0;
                    ds.roe              += 0.2;
                    ds.ecosystemRevenue += 8;
                    partnerNarrative = 'Alianza AgriCredit activa: +1.0% participación, +0.2pp RoE por expansión rural crediticia.';
                } else if (d.partnership === 'techbank') {
                    ds.costToIncome -= 2;
                    ds.brandTrust   -= 8;
                    partnerNarrative = 'Alianza TechBank: -2pp Costo/Ingreso pero riesgo de privacidad afecta confianza de marca (-8 pts).';
                } else {
                    partnerNarrative = 'Sin alianza estratégica este periodo. BancaVerde consolida plataforma interna.';
                }
            } else if (period === 2) {
                if (ds.apiReady < 50) {
                    ds.roe          -= 2.0;
                    ds.brandTrust   -= 25;
                    ds.regulatoryFined = true;
                    regEvent = '⚠️ MULTA REGULATORIA: BCA impone sanción por incumplimiento API. RoE -2.0pp, Confianza -25pts, costo AV$45M.';
                } else {
                    ds.ecosystemRevenue += 20;
                    regEvent = '✅ Open Banking: BancaVerde cumple Decreto Fintech 2024. Ventaja de primer movedor en monetización API.';
                }

                if (d.partnership === 'acquire') {
                    ds.marketShare        += 4.5;
                    ds.digitalPenetration += 10;
                    ds.digitalNPS         += 12;
                    ds.roe                -= 1.5;
                    ds.brandTrust         -= 5;
                    ds.acquisitionChoice   = 'acquire';
                    partnerNarrative = 'Adquisición de NeoBanca Verde aprobada: +4.5pp mercado, +10pp penetración digital. Costo de integración: -1.5pp RoE.';
                } else if (d.partnership === 'partner') {
                    ds.marketShare        += 1.5;
                    ds.ecosystemRevenue   += 30;
                    ds.digitalPenetration += 5;
                    ds.acquisitionChoice   = 'partner';
                    partnerNarrative = 'Alianza estratégica con NeoBanca Verde: acceso a base de clientes, AV$30M ingresos ecosistema.';
                } else {
                    ds.roe         += 0.3;
                    ds.brandTrust  += 5;
                    ds.acquisitionChoice = 'reject';
                    partnerNarrative = 'BancaVerde elige competencia independiente: capital conservado (+0.3pp RoE), narrativa de fortaleza institucional.';
                }
            } else if (period === 3) {
                ds.nim         -= 0.3;
                ds.marketShare -= 0.5;
                regEvent = 'Banco Central lanza ataque de precios: cuentas sin comisión y 4.0% ahorro. NIM -0.3pp, participación -0.5pp.';

                // Persistent non-compliance compounds: a team that was fined in Round 2 and
                // STILL hasn't reached 50% API readiness pays again (fix for B2).
                if (ds.regulatoryFined && ds.apiReady < 50) {
                    ds.brandTrust -= 10;
                    ds.roe        -= 0.5;
                    regEvent += ' ⚠️ Incumplimiento persistente agrava la sanción: Confianza -10pts adicionales, RoE -0.5pp.';
                }

                if (d.partnership === 'ecosystem_leader') {
                    ds.ecosystemRevenue += 40;
                    ds.marketShare      += 1.0;
                    ds.digitalNPS       += 8;
                    ds.finalPositioning  = 'ecosystem_leader';
                    partnerNarrative = 'Posicionamiento como Líder del Ecosistema: AV$40M ingresos adicionales, +1.0pp mercado, NPS +8pts.';
                } else if (d.partnership === 'niche_sme') {
                    ds.roe         += 0.8;
                    ds.marketShare += 0.5;
                    ds.finalPositioning = 'niche_sme';
                    partnerNarrative = 'Especialización PYME Premium: +0.8pp RoE, +0.5pp participación en segmento de alto valor.';
                } else {
                    ds.brandTrust      += 10;
                    ds.finalPositioning = 'acquisition_ready';
                    partnerNarrative = 'Optimización para adquisición: balance simplificado, activos digitales valorizados para comprador estratégico.';
                }
            }

            ds._regEvent      = regEvent;
            ds._partnerNarr   = partnerNarrative;

            // Product launch effects
            if (round && d.product !== 'none') {
                var prod = null;
                for (var pi = 0; pi < round.productOptions.length; pi++) {
                    if (round.productOptions[pi].id === d.product) { prod = round.productOptions[pi]; break; }
                }
                if (prod) {
                    if (prod.dpBonus)          ds.digitalPenetration += prod.dpBonus;
                    if (prod.msBonus)          ds.marketShare        += prod.msBonus;
                    if (prod.roeBonus)         ds.roe                += prod.roeBonus;
                    if (prod.ecoBonus)         ds.ecosystemRevenue   += prod.ecoBonus;
                    if (prod.npsBonus)         ds.digitalNPS         += prod.npsBonus;
                    if (prod.costIncomeBonus)  ds.costToIncome       += prod.costIncomeBonus;
                    ds.roe -= prod.cost * 0.005;
                }
            }

            // Workforce
            ds.branchesClosed += d.branchClosures;
            ds.costToIncome   -= d.branchClosures * 0.04;
            if (d.branchClosures > 20) ds.brandTrust -= (d.branchClosures - 20) * 0.5;

            ds.engineerTeams      += d.engineerHires;
            ds.digitalPenetration += d.engineerHires * 2;
            ds.digitalNPS         += d.engineerHires;
            ds.costToIncome       -= d.engineerHires * 0.5;

            // Market pressure
            ds.nim -= 0.15;

            // Bounds
            ds.digitalPenetration = Math.min(95, Math.max(34, ds.digitalPenetration));
            ds.digitalNPS         = Math.min(80, Math.max(20, ds.digitalNPS));
            ds.costToIncome       = Math.min(75, Math.max(38, ds.costToIncome));
            ds.roe                = Math.min(20, Math.max(4,  ds.roe));
            ds.nim                = Math.max(2.4, ds.nim);
            ds.brandTrust         = Math.min(100, Math.max(10, ds.brandTrust));
            ds.marketShare        = Math.min(26,  Math.max(11, ds.marketShare));

            // Scoring (out of 100)
            var roeScore  = Math.min(12, Math.max(0, (ds.roe - 11) * 3 + 6));
            var ciScore   = Math.min(12, Math.max(0, (68 - ds.costToIncome) * 0.5 + 4));
            var nimScore  = Math.min(6,  Math.max(0, (ds.nim - 2.4) * 3 + 3));
            var ecoScore  = Math.min(5,  Math.max(0, ds.ecosystemRevenue / 30));
            var financialScore = Math.round(roeScore + ciScore + nimScore + ecoScore);

            var dpScore   = Math.min(15, Math.max(0, (ds.digitalPenetration - 34) * 0.3 + 3));
            var npsScore  = Math.min(10, Math.max(0, (ds.digitalNPS - 28) * 0.35 + 2));
            var apiScore  = Math.min(5,  Math.max(0, ds.apiReady * 0.05));
            var digitalScore = Math.round(dpScore + npsScore + apiScore);

            var msScore   = Math.min(10, Math.max(0, (ds.marketShare - 17) * 3 + 7));
            var btScore   = Math.min(6,  Math.max(0, (ds.brandTrust - 50) * 0.1 + 3));
            var ptScore   = (d.partnership !== 'none' && d.partnership !== 'reject') ? 4 : 1;
            var marketScore = Math.round(msScore + btScore + ptScore);

            var engScore   = Math.min(6, ds.engineerTeams * 1.5);
            var branchScore= Math.min(5, ds.branchesClosed * 0.1);
            // Compliance sub-score now allows partial recovery: a team fined in Round 2
            // that catches up to >=50% API readiness by the time this is scored keeps some
            // credit, instead of a permanent 0 for the rest of the game (fix for B2).
            var compScore;
            if (!ds.regulatoryFined) {
                compScore = 4;
            } else if (ds.apiReady >= 50) {
                compScore = 2;
            } else {
                compScore = 0;
            }
            var orgScore   = Math.round(engScore + branchScore + compScore);

            var periodScore = Math.min(100, financialScore + digitalScore + marketScore + orgScore);
            ds.periodScore    = periodScore;
            ds.scoreFinancial = financialScore;
            ds.scoreDigital   = digitalScore;
            ds.scoreMarket    = marketScore;
            ds.scoreOrg       = orgScore;

            // Write by period index (not push) so resubmitting a period overwrites its
            // slot instead of appending a duplicate row. totalScore is then derived as a
            // fresh sum of scoreHistory (not accumulated with +=) so it is always correct
            // regardless of how many times any period was resubmitted.
            ds.scoreHistory[period - 1]       = periodScore;
            ds.marketShareHistory[period - 1] = parseFloat(ds.marketShare.toFixed(1));
            ds.digitalPenHistory[period - 1]  = parseFloat(ds.digitalPenetration.toFixed(1));
            ds.roeHistory[period - 1]         = parseFloat(ds.roe.toFixed(1));
            ds.totalScore = ds.scoreHistory.reduce(function(sum, v) { return sum + (v || 0); }, 0);

            var self   = this;
            var capReg = regEvent;
            var capPar = partnerNarrative;
            var capFs  = financialScore;
            var capDs2 = digitalScore;
            var capMs  = marketScore;
            var capOs  = orgScore;
            var capPs  = periodScore;
            var nextPer = state.currentPeriod + 1;
            var capDs3 = state.domainState;

            setTimeout(function() {
                var panel = document.getElementById('scorePanelDiv');
                if (panel) panel.style.display = 'block';
                var sf = document.getElementById('scoreFinancial');
                if (sf) sf.textContent = capFs + '/35';
                var sd = document.getElementById('scoreDigital');
                if (sd) sd.textContent = capDs2 + '/30';
                var sm = document.getElementById('scoreMarket');
                if (sm) sm.textContent = capMs + '/20';
                var so = document.getElementById('scoreOrg');
                if (so) so.textContent = capOs + '/15';
                var st = document.getElementById('scoreTotalDisplay');
                if (st) st.textContent = capPs + '/100';
                var rn = document.getElementById('resultsNarrative');
                if (rn) {
                    var html = '';
                    if (capReg) html += '<p class="bv-event-highlight">' + capReg + '</p>';
                    html += '<p>' + capPar + '</p>';
                    rn.innerHTML = html;
                }
                self._updateBriefing({ currentPeriod: nextPer, domainState: capDs3 });
                self._updatePartnershipOptions({ currentPeriod: nextPer, domainState: capDs3 });
                self._updateProductOptions({ currentPeriod: nextPer, domainState: capDs3 });
            }, 500);

            return {
                period:             period,
                marketShare:        parseFloat(ds.marketShare.toFixed(1)),
                digitalPenetration: parseFloat(ds.digitalPenetration.toFixed(1)),
                costToIncome:       parseFloat(ds.costToIncome.toFixed(1)),
                roe:                parseFloat(ds.roe.toFixed(1)),
                digitalNPS:         ds.digitalNPS,
                apiReady:           Math.round(ds.apiReady),
                periodScore:        periodScore
            };
        }

