        getPerformanceSummary(history) {
            if (!history.length) return {};
            var total = 0;
            history.forEach(function(r) { total += (r.results && r.results.periodScore) ? r.results.periodScore : 0; });
            var last = history[history.length - 1];
            var finalMs  = (last.results && last.results.marketShare)        ? last.results.marketShare        : 17;
            var finalDp  = (last.results && last.results.digitalPenetration) ? last.results.digitalPenetration : 34;
            var finalRoe = (last.results && last.results.roe)                ? last.results.roe                : 11;

            var performance = 'Banco en Riesgo';
            var insights = ['BancaVerde necesita acelerar su transformación digital para sobrevivir a la disrupción fintech.'];

            if (total >= 195) {
                performance = 'Líder Digital de Arvelia';
                insights = [
                    'BancaVerde logró una transformación digital exitosa y lidera el ecosistema fintech de Arvelia.',
                    'La combinación de inversión tecnológica disciplinada y gestión financiera sólida creó ventaja competitiva sostenible.'
                ];
            } else if (total >= 150) {
                performance = 'Transformador Sólido';
                insights = [
                    'BancaVerde avanzó significativamente en su transformación digital.',
                    'Hay oportunidades adicionales en monetización del ecosistema API y mayor reducción de costos operativos.'
                ];
            } else if (total >= 105) {
                performance = 'En Transición';
                insights = [
                    'BancaVerde inició la transformación pero enfrenta presión competitiva creciente de neobancos.',
                    'Se recomienda mayor inversión en Mobile/UX y reducción acelerada de sucursales físicas en la próxima iteración.'
                ];
            }

            return {
                totalScore:              total,
                finalMarketShare:        finalMs + '%',
                finalDigitalPenetration: finalDp + '%',
                finalRoE:                finalRoe + '%',
                performance:             performance,
                insights:                insights
            };
        }

